        const float* cos_row;
        const float* sin_row;
        if (cos_bs == 1) {
            cos_row = cos_ptr + seq_idx * cos_sl_stride;
            sin_row = sin_ptr + seq_idx * sin_sl_stride;
        } else {
            cos_row = cos_ptr + batch_idx * (sl * cos_sl_stride) + seq_idx * cos_sl_stride;
            sin_row = sin_ptr + batch_idx * (sl * sin_sl_stride) + seq_idx * sin_sl_stride;
        }

