            scalar_t* q_out_row = q_out + row_idx * n_qh * hd + h * hd;
            const scalar_t* q_in_row = q_in + row_idx * n_qh * hd + h * hd;

            // Vectorized processing of first and second half
            for (int i = threadIdx.x * VEC_SIZE; i < hd_half; i += blockDim.x * VEC_SIZE) {
