Rotary Position Embedding (RoPE) - Optimized CUDA for H100
Memory-bound kernel with vectorization and shared memory
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_bf16.h>
#include <cuda_fp16.h>

// Vector load/store helpers
template<typename T, int N> struct VecType;
template<> struct VecType<float, 4> { using type = float4; };
template<> struct VecType<float, 2> { using type = float2; };
template<> struct VecType<__half, 4> { using type = ulong2; };
template<> struct VecType<__half, 2> { using type = uint; };
template<> struct VecType<nv_bfloat16, 4> { using type = ulong2; };
template<> struct VecType<nv_bfloat16, 2> { using type = uint; };

// Optimized RoPE kernel with shared memory for cos/sin
template <typename scalar_t, int VEC_ELEMS>
__launch_bounds__(256, 4)
__global__ void rope_kernel_shared(
    scalar_t* __restrict__ q_out,
    const scalar_t* __restrict__ q_in,
    scalar_t* __restrict__ k_out,
    const scalar_t* __restrict__ k_in,
    const float* __restrict__ cos_ptr,
    const float* __restrict__ sin_ptr,
    const int bs, const int sl, const int n_qh, const int n_kh, const int hd,
    const int cos_bs, const int cos_sl_stride, const int sin_sl_stride
) {
    const int hd_half = hd / 2;
    const int total_rows = bs * sl;

    // Shared memory for cos/sin - cached per block
    extern __shared__ float shared_cos_sin[];
    float* shared_cos = shared_cos_sin;
    float* shared_sin = shared_cos_sin + hd_half;

    // Grid-stride loop over rows
    for (int row_idx = blockIdx.x; row_idx < total_rows; row_idx += gridDim.x) {
        const int batch_idx = row_idx / sl;
        const int seq_idx = row_idx % sl;

        // Cooperative load of cos/sin into shared memory
        for (int i = threadIdx.x; i < hd_half; i += blockDim.x) {
            const float* cos_row = (cos_bs == 1) 
                ? cos_ptr + seq_idx * cos_sl_stride
                : cos_ptr + batch_idx * (sl * cos_sl_stride) + seq_idx * cos_sl_stride;
            const float* sin_row = (cos_bs == 1)
                ? sin_ptr + seq_idx * sin_sl_stride
                : sin_ptr + batch_idx * (sl * sin_sl_stride) + seq_idx * sin_sl_stride;
            shared_cos[i] = cos_row[i];
            shared_sin[i] = sin_row[i];
        }
        __syncthreads();

        // Process Q heads
        const int q_row_offset = row_idx * n_qh * hd;
        const int total_q_elems = n_qh * hd_half;

        for (int idx = threadIdx.x; idx < total_q_elems; idx += blockDim.x) {
            const int h = idx / hd_half;
            const int i = idx % hd_half;

            const float c = shared_cos[i];
            const float s = shared_sin[i];

            const scalar_t* q_in_row = q_in + q_row_offset + h * hd;
            scalar_t* q_out_row = q_out + q_row_offset + h * hd;

            const float q1 = float(q_in_row[i]);
            const float q2 = float(q_in_row[i + hd_half]);

            q_out_row[i] = scalar_t(q1 * c - q2 * s);
            q_out_row[i + hd_half] = scalar_t(q2 * c + q1 * s);
        }

        // Process K heads
        const int k_row_offset = row_idx * n_kh * hd;
        const int total_k_elems = n_kh * hd_half;

        for (int idx = threadIdx.x; idx < total_k_elems; idx += blockDim.x) {
            const int h = idx / hd_half;
            const int i = idx % hd_half;

            const float c = shared_cos[i];
            const float s = shared_sin[i];

            const scalar_t* k_in_row = k_in + k_row_offset + h * hd;
            scalar_t* k_out_row = k_out + k_row_offset + h * hd;

            const float k1 = float(k_in_row[i]);
            const float k2 = float(k_in_row[i + hd_half]);

            k_out_row[i] = scalar_t(k1 * c - k2 * s);
            k_out_row[i + hd_half] = scalar_t(k2 * c + k1 * s);
        }
    }
}

// Vectorized version using float4 for cos/sin
template <typename scalar_t>
__launch_bounds__(256, 4)
__global__ void rope_kernel_vec4_opt(
    scalar_t* __restrict__ q_out,
    const scalar_t* __restrict__ q_in,
    scalar_t* __restrict__ k_out,
    const scalar_t* __restrict__ k_in,
    const float* __restrict__ cos_ptr,
    const float* __restrict__ sin_ptr,
    const int bs, const int sl, const int n_qh, const int n_kh, const int hd,
    const int cos_bs, const int cos_sl_stride, const int sin_sl_stride
) {
    const int hd_half = hd / 2;
    const int total_rows = bs * sl;
    const int hd_half_vec = hd_half / 4;

    // Shared memory for vectorized cos/sin
    __shared__ float4 shared_cos_vec[32];  // Max 128 elements (hd=256)
    __shared__ float4 shared_sin_vec[32];

    float4* s_cos = shared_cos_vec;
    float4* s_sin = shared_sin_vec;

    for (int row_idx = blockIdx.x; row_idx < total_rows; row_idx += gridDim.x) {
        const int batch_idx = row_idx / sl;
        const int seq_idx = row_idx % sl;

        const float* cos_row = (cos_bs == 1) 
            ? cos_ptr + seq_idx * cos_sl_stride
            : cos_ptr + batch_idx * (sl * cos_sl_stride) + seq_idx * cos_sl_stride;
        const float* sin_row = (cos_bs == 1)
            ? sin_ptr + seq_idx * sin_sl_stride
            : sin_ptr + batch_idx * (sl * sin_sl_stride) + seq_idx * sin_sl_stride;

        // Load cos/sin with float4
        const float4* cos_vec = reinterpret_cast<const float4*>(cos_row);
        const float4* sin_vec = reinterpret_cast<const float4*>(sin_row);

        for (int i = threadIdx.x; i < hd_half_vec; i += blockDim.x) {
            s_cos[i] = cos_vec[i];
            s_sin[i] = sin_vec[i];
        }
        __syncthreads();

        // Process Q heads
        const int q_row_offset = row_idx * n_qh * hd;
        const int total_q_elems = n_qh * hd_half_vec;

        for (int idx = threadIdx.x; idx < total_q_elems; idx += blockDim.x) {
            const int h = idx / hd_half_vec;
            const int vec_i = idx % hd_half_vec;
            const int i = vec_i * 4;

            const float4 c4 = s_cos[vec_i];
            const float4 s4 = s_sin[vec_i];

            const scalar_t* q_in_row = q_in + q_row_offset + h * hd;
            scalar_t* q_out_row = q_out + q_row_offset + h * hd;

            #pragma unroll
            for (int v = 0; v < 4; v++) {
                const float c = (&c4.x)[v];
                const float s = (&s4.x)[v];
                const float q1 = float(q_in_row[i + v]);
                const float q2 = float(q_in_row[i + v + hd_half]);
                q_out_row[i + v] = scalar_t(q1 * c - q2 * s);
                q_out_row[i + v + hd_half] = scalar_t(q2 * c + q1 * s);
            }
        }

        // Process K heads
        const int k_row_offset = row_idx * n_kh * hd;
        const int total_k_elems = n_kh * hd_half_vec;

        for (int idx = threadIdx.x; idx < total_k_elems; idx += blockDim.x) {
            const int h = idx / hd_half_vec;
            const int vec_i = idx % hd_half_vec;
            const int i = vec_i * 4;

            const float4 c4 = s_cos[vec_i];
            const float4 s4 = s_sin[vec_i];

            const scalar_t* k_in_row = k_in + k_row_offset + h * hd;
            scalar_t* k_out_row = k_out + k_row_offset + h * hd;

            #pragma unroll
            for (int v = 0; v < 4; v++) {
                const float c = (&c4.x)[v];
                const float s = (&s4.x)[v];
                const float k1 = float(k_in_row[i + v]);
                const float k2 = float(k_in_row[i + v + hd_half]);
                k_out_row[i + v] = scalar_t(k1 * c - k2 * s);
                k_out_row[i + v + hd_half] = scalar_t(k2 * c + k1 * s);
            }
        }
    }
}

// Simple high-performance kernel without shared memory (relies on L2 cache)
template <typename scalar_t>
__launch_bounds__(512, 2)
__global__ void rope_kernel_simple(
    scalar_t* __restrict__ q_out,
    const scalar_t* __restrict__ q_in,
    scalar_t* __restrict__ k_out,
    const scalar_t* __restrict__ k_in,
    const float* __restrict__ cos_ptr,
    const float* __restrict__ sin_ptr,
    const int bs, const int sl, const int n_qh, const int n_kh, const int hd,
    const int cos_bs, const int cos_sl_stride, const int sin_sl_stride
) {
    const int total_rows = bs * sl;
    const int hd_half = hd / 2;

    for (int row_idx = blockIdx.x; row_idx < total_rows; row_idx += gridDim.x) {
        const int batch_idx = row_idx / sl;
        const int seq_idx = row_idx % sl;

        const float* cos_row = (cos_bs == 1) 
            ? cos_ptr + seq_idx * cos_sl_stride
            : cos_ptr + batch_idx * (sl * cos_sl_stride) + seq_idx * cos_sl_stride;
        const float* sin_row = (cos_bs == 1)
            ? sin_ptr + seq_idx * sin_sl_stride
            : sin_ptr + batch_idx * (sl * sin_sl_stride) + seq_idx * sin_sl_stride;

        // Process all Q elements
        const int q_base = row_idx * n_qh * hd;
        const int total_q = n_qh * hd_half;

        for (int idx = threadIdx.x; idx < total_q; idx += blockDim.x) {
            const int h = idx / hd_half;
            const int i = idx % hd_half;

            const float c = cos_row[i];
            const float s = sin_row[i];

            const int offset1 = q_base + h * hd + i;
            const int offset2 = q_base + h * hd + i + hd_half;

            const float q1 = float(q_in[offset1]);
            const float q2 = float(q_in[offset2]);

            q_out[offset1] = scalar_t(q1 * c - q2 * s);
            q_out[offset2] = scalar_t(q2 * c + q1 * s);
        }

        // Process all K elements
        const int k_base = row_idx * n_kh * hd;
        const int total_k = n_kh * hd_half;

        for (int idx = threadIdx.x; idx < total_k; idx += blockDim.x) {
            const int h = idx / hd_half;
            const int i = idx % hd_half;

            const float c = cos_row[i];
            const float s = sin_row[i];

            const int offset1 = k_base + h * hd + i;
            const int offset2 = k_base + h * hd + i + hd_half;

            const float k1 = float(k_in[offset1]);
            const float k2 = float(k_in[offset2]);

            k_out[offset1] = scalar_t(k1 * c - k2 * s);
            k_out[offset2] = scalar_t(k2 * c + k1 * s);
        }
    }
}

// Dispatch function
std::tuple<torch::Tensor, torch::Tensor> rope_cuda(
    const torch::Tensor& q,
    const torch::Tensor& k,
    const torch::Tensor& cos,
    const torch::Tensor& sin
) {
    const int bs = q.size(0);
    const int sl = q.size(1);
    const int n_qh = q.size(2);
    const int hd = q.size(3);
    const int n_kh = k.size(2);
    const int cos_bs = cos.size(0);
    const int cos_sl_stride = cos.stride(-2);
    const int sin_sl_stride = sin.stride(-2);

    auto q_out = torch::empty_like(q);
    auto k_out = torch::empty_like(k);

    const int total_rows = bs * sl;
    const int hd_half = hd / 2;

    // Choose configuration based on dimensions
    int block_size, grid_size;
    size_t shared_mem = 0;

    // For smaller dimensions, use shared memory
    // For larger dimensions, rely on L2 cache
    bool use_shared = (hd_half <= 128);

    if (use_shared) {
        block_size = 256;
        grid_size = std::min(total_rows, 132 * 4);
        shared_mem = 2 * hd_half * sizeof(float);
    } else {
        block_size = 512;
        grid_size = std::min(total_rows, 132 * 2);
    }

    AT_DISPATCH_FLOATING_TYPES_AND2(
        torch::kBFloat16, torch::kHalf, q.scalar_type(), "rope_kernel", ([&] {
            if (use_shared) {
                if (hd_half % 4 == 0 && hd_half <= 128) {
                    rope_kernel_vec4_opt<scalar_t><<<grid_size, block_size>>>(
                        q_out.data_ptr<scalar_t>(),
                        q.data_ptr<scalar_t>(),
                        k_out.data_ptr<scalar_t>(),
                        k.data_ptr<scalar_t>(),
                        cos.data_ptr<float>(),
                        sin.data_ptr<float>(),
                        bs, sl, n_qh, n_kh, hd, cos_bs, cos_sl_stride, sin_sl_stride
                    );
                } else {
                    rope_kernel_shared<scalar_t, 1><<<grid_size, block_size, shared_mem>>>(
                        q_out.data_ptr<scalar_t>(),
                        q.data_ptr<scalar_t>(),
                        k_out.data_ptr<scalar_t>(),
                        k.data_ptr<scalar_t>(),
                        cos.data_ptr<float>(),
                        sin.data_ptr<float>(),
                        bs, sl, n_qh, n_kh, hd, cos_bs, cos_sl_stride, sin_sl_stride
                    );
                }
            } else {
                rope_kernel_simple<scalar_t><<<grid_size, block_size>>>(
                    q_out.data_ptr<scalar_t>(),
                    q.data_ptr<scalar_t>(),
                    k_out.data_ptr<scalar_t>(),
                    k.data_ptr<scalar_t>(),
                    cos.data_ptr<float>(),
                    sin.data_ptr<float>(),
                    bs, sl, n_qh, n_kh, hd, cos_bs, cos_sl_stride, sin_sl_stride
                );
            }
        })
    );

    return std::make_tuple(q_out, k_out);
}
